<?php require '../config/auth.php';login_required('company');$page_title='Manage Jobs';$q=$pdo->prepare('SELECT id FROM companies WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$cid=$q->fetch()['id'];$q=$pdo->prepare('SELECT j.*,COUNT(a.id) applicants FROM jobs j LEFT JOIN applications a ON a.job_id=j.id WHERE j.company_id=? GROUP BY j.id ORDER BY j.created_at DESC');$q->execute([$cid]);$rows=$q->fetchAll();require '../config/header.php';flashes();?><div class="head"><div><h1>Manage Jobs</h1><p>Track approval and applicant counts.</p></div><a class="btn primary" href="post-job.php">+ Post Job</a></div><div class="card tablewrap"><table class="table"><tr><th>Job</th><th>Deadline</th><th>Applicants</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['job_title'])?></b><br><small><?=e($r['location'])?></small></td><td><?=e($r['application_deadline'])?></td><td><?=$r['applicants']?></td><td><span class="badge <?=$r['status']==='approved'?'green':($r['status']==='rejected'?'red':'orange')?>"><?=e($r['status'])?></span></td><td><a class="btn outline sm" href="applicants.php?job_id=<?=$r['id']?>">Applicants</a></td></tr><?php endforeach;?></table><?php if(!$rows):?><div class="empty">No jobs posted.</div><?php endif;?></div><?php require '../config/footer.php';?>
